/* ==========================================================================
   FertGrow CMMS — Programação Semanal
   Lê os PDFs de OS anexados (um arquivo pode conter várias Ordens de
   Serviço), lista cada uma com checkbox de "Realizada" e mostra a
   aderência da semana em percentual, além de tabela consolidada,
   impressão, ZIP e envio por e-mail.
   ========================================================================== */

const LOGO_FERTGROW_B64 = "";

const DIAS_SEMANA_PROG = ['Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'];

// Segunda-feira da semana que contém a data informada (a semana da Programação
// começa na segunda-feira, não no domingo — alinhado ao relatório semanal da empresa).
function progInicioSemana(dataISO) {
  const d = new Date(dataISO + 'T00:00:00');
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // volta até a Segunda-feira (getDay(): 0=Dom..6=Sáb)
  return d.toISOString().slice(0, 10);
}
function progAddDays(dataISO, n) {
  const d = new Date(dataISO + 'T00:00:00');
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}
function progDiaSemanaLabel(dataISO) {
  return DIAS_SEMANA_PROG[new Date(dataISO + 'T00:00:00').getDay()];
}
function progDiasDaSemana(inicioSemana) {
  return Array.from({ length: 7 }, (_, i) => progAddDays(inicioSemana, i));
}
function progEntry(dataISO) {
  return Store.all('programacao').find(p => p.data === dataISO) || null;
}
// Uma OS cancelada com justificativa conta como positiva na aderência —
// não é tratada como pendência de planejamento, só a "Realizada" de fato é diferente.
function progConta(o) { return !!(o.concluida || o.cancelada); }

// Aderência de um único dia (usado no badge de cada dia da semana).
function progAderenciaDia(dataISO) {
  const entry = progEntry(dataISO);
  let total = 0, concluidas = 0;
  (entry?.arquivos || []).forEach(a => (a.ordens || []).forEach(o => { total++; if (progConta(o)) concluidas++; }));
  return { total, concluidas, aderencia: total ? Math.round((concluidas / total) * 100) : 0 };
}
// Aderência de uma semana inteira (usado no card S-1 · Semana Anterior).
function progAderenciaSemana(inicioSemana) {
  let total = 0, concluidas = 0;
  progDiasDaSemana(inicioSemana).forEach(d => {
    const entry = progEntry(d);
    (entry?.arquivos || []).forEach(a => (a.ordens || []).forEach(o => { total++; if (progConta(o)) concluidas++; }));
  });
  return { total, concluidas, aderencia: total ? Math.round((concluidas / total) * 100) : 0 };
}
function progAnexar(dataISO, novosArquivos) {
  const entry = progEntry(dataISO);
  if (entry) Store.update('programacao', entry.id, { arquivos: [...entry.arquivos, ...novosArquivos] });
  else Store.add('programacao', { data: dataISO, observacao: '', arquivos: novosArquivos });
}
function progRemoverArquivo(dataISO, arquivoId) {
  const entry = progEntry(dataISO);
  if (!entry) return;
  Store.update('programacao', entry.id, { arquivos: entry.arquivos.filter(a => a.id !== arquivoId) });
}
// Remove uma única OS do dia (não o "arquivo" inteiro que a trouxe) — usado pelos
// cards de dia, que agora listam as OS direto, sem expor o conceito de arquivo.
function progRemoverOrdem(dataISO, arquivoId, ordemId) {
  const entry = progEntry(dataISO);
  if (!entry) return;
  const arquivos = entry.arquivos
    .map(a => a.id === arquivoId ? { ...a, ordens: (a.ordens || []).filter(o => o.id !== ordemId) } : a)
    .filter(a => (a.ordens || []).length > 0);
  Store.update('programacao', entry.id, { arquivos });
}
function progSalvarObservacao(dataISO, texto) {
  const entry = progEntry(dataISO);
  if (entry) Store.update('programacao', entry.id, { observacao: texto });
  else Store.add('programacao', { data: dataISO, observacao: texto, arquivos: [] });
}
function progToggleOrdem(dataISO, arquivoId, ordemId, concluida) {
  const entry = progEntry(dataISO);
  if (!entry) return;
  const arquivos = entry.arquivos.map(a => {
    if (a.id !== arquivoId) return a;
    return { ...a, ordens: a.ordens.map(o => o.id === ordemId ? { ...o, concluida } : o) };
  });
  Store.update('programacao', entry.id, { arquivos });
}
function progCancelarOrdem(dataISO, arquivoId, ordemId, motivo) {
  const entry = progEntry(dataISO);
  if (!entry) return;
  const arquivos = entry.arquivos.map(a => {
    if (a.id !== arquivoId) return a;
    return { ...a, ordens: a.ordens.map(o => o.id === ordemId ? { ...o, cancelada: true, motivoCancelamento: motivo, concluida: false } : o) };
  });
  Store.update('programacao', entry.id, { arquivos });
}
function progReabrirOrdem(dataISO, arquivoId, ordemId) {
  const entry = progEntry(dataISO);
  if (!entry) return;
  const arquivos = entry.arquivos.map(a => {
    if (a.id !== arquivoId) return a;
    return { ...a, ordens: a.ordens.map(o => o.id === ordemId ? { ...o, cancelada: false, motivoCancelamento: '' } : o) };
  });
  Store.update('programacao', entry.id, { arquivos });
}
function progAbrirCancelarOS(dataISO, arquivoId, ordemId) {
  const body = document.createElement('div');
  body.innerHTML = `
    <p class="text-muted" style="font-size:12.5px;margin-bottom:10px;">Cancelar esta OS. Uma OS cancelada com justificativa conta como positiva na aderência da semana (não entra como pendência de planejamento).</p>
    <div class="field"><label>Justificativa</label><textarea id="motivoCancelOS" placeholder="Ex: equipamento parado por decisão da produção, falta de peça, etc." style="width:100%;min-height:80px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px;padding:8px;color:var(--text);font-size:12.5px;"></textarea></div>
  `;
  const footer = document.createElement('div');
  footer.style.cssText = 'display:flex;gap:8px;width:100%;justify-content:flex-end;';
  footer.innerHTML = `<button class="btn" id="cancelCancelOS">Voltar</button><button class="btn btn-danger" id="confirmCancelOS">${Icon('x', 15)} Confirmar Cancelamento</button>`;
  App.openModal({ title: 'Cancelar OS', body, footer });
  renderIcons();
  document.getElementById('cancelCancelOS').onclick = App.closeModal;
  document.getElementById('confirmCancelOS').onclick = () => {
    const motivo = document.getElementById('motivoCancelOS').value.trim();
    if (!motivo) { App.toast('Informe a justificativa do cancelamento.', 'danger'); return; }
    progCancelarOrdem(dataISO, arquivoId, ordemId, motivo);
    App.toast('OS cancelada com justificativa — contabilizada na aderência.', 'success');
    App.closeModal();
    App.navigate('programacao', true);
  };
}

function progBadgeTipoOS(tipo) {
  const t = progNormalizar(tipo || '');
  if (t.includes('corretiv')) return 'danger';
  if (t.includes('inspec')) return 'warning';
  if (t.includes('prevent')) return 'info';
  return 'neutral';
}

// Converte a duração de uma célula do Excel para "HH:MM". Colunas de hora/duração
// sem a opção cellDates chegam do SheetJS como fração do dia (ex.: 0.5/24 = "00:30"),
// não como texto — sem isso, o valor viraria um número decimal sem sentido na tela.
function formatarDuracaoExcel(valor) {
  if (valor === '' || valor === null || valor === undefined) return '';
  if (typeof valor === 'number') {
    const totalMin = Math.round(valor * 24 * 60);
    const h = Math.floor(totalMin / 60), m = totalMin % 60;
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }
  return String(valor).trim();
}

function progDataURLtoArrayBuffer(dataurl) {
  const base64 = dataurl.split(',')[1];
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

// Colunas fixas e conhecidas do relatório "Programação Semanal" (mesmas do Excel).
const PROG_COLUNAS_GRADE = ['OS', 'Código Externo', 'Descrição OS', 'TAG', 'Ativo', 'Executante', 'Oficina', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sab', 'Dom'];

// Agrupa os fragmentos de texto de uma página de PDF por linha (posição Y), mantendo a
// posição X de cada fragmento — para depois distribuir nas colunas certas por posição.
function progAgruparLinhasPDF(items) {
  const linhas = [];
  items.forEach(it => {
    const y = Math.round(it.transform[5]);
    let linha = linhas.find(l => Math.abs(l.y - y) <= 2);
    if (!linha) { linha = { y, itens: [] }; linhas.push(linha); }
    linha.itens.push({ texto: it.str, x: it.transform[4] });
  });
  linhas.sort((a, b) => b.y - a.y);
  linhas.forEach(l => l.itens.sort((a, b) => a.x - b.x));
  return linhas.filter(l => l.itens.some(it => it.texto.trim()));
}

// Tenta casar a sequência PROG_COLUNAS_GRADE contra os fragmentos de uma linha (cada
// rótulo pode ocupar mais de um fragmento, ex.: "Descrição" + "OS"). Devolve a posição X
// de início de cada coluna se a linha for o cabeçalho, ou null caso contrário.
function progDetectarCabecalhoGrade(itensLinha) {
  const xColunas = [];
  let cursor = 0;
  for (const coluna of PROG_COLUNAS_GRADE) {
    if (cursor >= itensLinha.length) return null;
    const xInicio = itensLinha[cursor].x;
    // tenta casar o rótulo inteiro como um fragmento só (ex.: "Descrição OS" pode
    // vir junto, dependendo de como o pdf.js segmentou o texto da página)
    const alvoJunto = progNormalizar(coluna).replace(/\s+/g, '');
    if (progNormalizar(itensLinha[cursor].texto).replace(/\s+/g, '') === alvoJunto) {
      cursor++;
      xColunas.push(xInicio);
      continue;
    }
    // senão, tenta casar consumindo um fragmento por palavra do rótulo
    const palavras = coluna.split(' ').map(progNormalizar);
    let cursorTentativa = cursor;
    const ok = palavras.every(palavra => {
      if (cursorTentativa >= itensLinha.length || progNormalizar(itensLinha[cursorTentativa].texto) !== palavra) return false;
      cursorTentativa++;
      return true;
    });
    if (!ok) return null;
    cursor = cursorTentativa;
    xColunas.push(xInicio);
  }
  return xColunas;
}

// A partir das posições X de cada coluna (ponto médio entre colunas vizinhas como
// limite), distribui os fragmentos de uma linha de dados nas colunas certas.
function progMontarLinhaGrade(itensLinha, xColunas) {
  const limites = xColunas.map((x, i) => i < xColunas.length - 1 ? (x + xColunas[i + 1]) / 2 : Infinity);
  const valores = PROG_COLUNAS_GRADE.map(() => []);
  itensLinha.forEach(it => {
    let col = 0;
    while (col < limites.length - 1 && it.x >= limites[col]) col++;
    valores[col].push(it.texto);
  });
  const row = {};
  PROG_COLUNAS_GRADE.forEach((nome, i) => { row[nome] = valores[i].join(' ').trim(); });
  return row;
}

// Lê a grade semanal a partir de um PDF (o mesmo relatório do Excel, mas em texto
// posicionado). Menos confiável que o Excel — por isso o resultado sempre passa por uma
// prévia antes de ser importado de fato (ver progAbrirImportarGrade).
async function progExtrairGradeDoPDF(dataURL) {
  const buffer = progDataURLtoArrayBuffer(dataURL);
  const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
  const rows = [];
  let xColunas = null;
  for (let p = 1; p <= Math.min(pdf.numPages, 30); p++) {
    const page = await pdf.getPage(p);
    const content = await page.getTextContent();
    const linhas = progAgruparLinhasPDF(content.items);
    linhas.forEach(l => {
      if (!xColunas) {
        const tentativa = progDetectarCabecalhoGrade(l.itens);
        if (tentativa) xColunas = tentativa; // linha de cabeçalho — não é dado
        return;
      }
      const row = progMontarLinhaGrade(l.itens, xColunas);
      if (/^\d+$/.test(row['OS'])) rows.push(row); // descarta linhas sem nº de OS (legenda etc.)
    });
  }
  return rows;
}

function progRenderPreviewGrade(rows) {
  if (!rows.length) return '<div class="text-muted" style="font-size:12.5px;">Nenhuma linha reconhecida.</div>';
  const cols = Object.keys(rows[0]);
  return `<div class="table-wrap" style="max-height:320px;overflow:auto;"><table><thead><tr>${cols.map(c => `<th>${c}</th>`).join('')}</tr></thead>
    <tbody>${rows.slice(0, 8).map(r => `<tr>${cols.map(c => `<td>${r[c]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>
    <div class="text-muted mt-8" style="font-size:11.5px;">Exibindo até 8 de ${rows.length} linha(s) reconhecida(s). Confira se as colunas batem antes de confirmar.</div>`;
}

// Importa a grade semanal (planilha com colunas OS, Código Externo, Descrição OS, TAG,
// Ativo, Executante, Oficina e Seg..Dom) para os dias da semana atualmente exibida.
function progImportarGradeSemanal(rows, nomeArquivo, dataURL) {
  const dias = progDiasDaSemana(_progSemanaRef);
  // Cada dia aceita mais de um nome de coluna possível — o relatório impresso usa
  // "Seg"/"Ter"/... mas a planilha exportada do sistema usa "horaSegunda"/"horaTerca"/...
  // Ordem alinhada a `dias`, que agora começa na Segunda-feira.
  const chavesDia = [
    ['seg', 'segunda', 'horasegunda'],
    ['ter', 'terca', 'horaterca'],
    ['qua', 'quarta', 'horaquarta'],
    ['qui', 'quinta', 'horaquinta'],
    ['sex', 'sexta', 'horasexta'],
    ['sab', 'sabado', 'horasabado'],
    ['dom', 'domingo', 'horadomingo'],
  ];
  const porDia = new Map(); // dataISO -> ordens[]
  let novos = 0, ignorados = 0, semNumero = 0;

  rows.forEach(row => {
    const m = Importacao.normalizarLinha(row);
    const numero = String(Importacao.campo(m, 'os', 'nos', 'codigoos') || '').trim();
    if (!numero) { semNumero++; return; }
    const codigoExterno = String(Importacao.campo(m, 'codigoexterno') || '').trim();
    const servico = String(Importacao.campo(m, 'descricaoos', 'descricao') || '').trim();
    const tag = String(Importacao.campo(m, 'tag') || '').trim();
    const ativoNome = String(Importacao.campo(m, 'ativo') || '').trim();
    const executante = String(Importacao.campo(m, 'executante', 'nomeexec', 'nomeexecutante') || '').trim();
    const oficina = String(Importacao.campo(m, 'oficina') || '').trim();
    const statusOrigem = String(Importacao.campo(m, 'status') || '').trim();
    const bem = [tag, ativoNome].filter(Boolean).join(' — ');

    chavesDia.forEach((aliases, i) => {
      const cel = Importacao.campo(m, ...aliases);
      if (cel === '' || cel === null || cel === undefined) return; // dia não marcado
      const dataISO = dias[i];
      const jaExiste = (progEntry(dataISO)?.arquivos || [])
        .some(a => (a.ordens || []).some(o => o.numero === numero));
      if (jaExiste) { ignorados++; return; }

      const lista = porDia.get(dataISO) || [];
      lista.push({
        id: Store.uid('os'), numero, codigoExterno, tipo: '', bem, servico,
        area: oficina, oficina, tag, executante, statusOrigem,
        manutencao: '', emissao: '', sequencia: '',
        dataInicio: dataISO, hora: formatarDuracaoExcel(cel),
        etapas: [], concluida: false, cancelada: false, motivoCancelamento: '',
      });
      porDia.set(dataISO, lista);
      novos++;
    });
  });

  porDia.forEach((ordens, dataISO) => {
    progAnexar(dataISO, [{
      id: Store.uid('doc'), nome: nomeArquivo, mime: 'text/csv', tamanho: 0,
      data: dataURL, dataUpload: new Date().toISOString().slice(0, 10), ordens,
    }]);
  });

  App.toast(
    `${novos} OS importadas em ${porDia.size} dia(s) da semana de ${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])}.` +
    (ignorados ? ` ${ignorados} ignoradas (já existiam nesse dia).` : '') +
    (semNumero ? ` ${semNumero} linha(s) sem número de OS ignoradas.` : ''),
    'success'
  );
}

function progAbrirImportarGrade() {
  const dias = progDiasDaSemana(_progSemanaRef);
  const body = document.createElement('div');
  body.innerHTML = `
    <p class="text-muted" style="font-size:12.5px;margin-bottom:10px;">
      Envie a planilha (.xlsx, .xls, .csv) ou o PDF da grade semanal de OS — colunas OS,
      Descrição OS, TAG, Ativo, Executante, Oficina e Seg a Dom. As OS serão adicionadas na
      semana <strong>atualmente exibida na tela: ${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])}</strong> —
      navegue até a semana certa antes de importar.
      <br>A leitura do PDF é menos confiável que a do Excel (depende do layout do relatório) —
      por isso, antes de importar de fato, você vê uma prévia das linhas reconhecidas.
    </p>
    <input type="file" id="inputImportarGrade" accept=".xlsx,.xls,.csv,.pdf" style="width:100%;">
  `;
  const footer = document.createElement('div');
  footer.style.cssText = 'display:flex;gap:8px;width:100%;justify-content:flex-end;';
  footer.innerHTML = `<button class="btn" id="cancelImportarGrade">Cancelar</button>`;
  App.openModal({ title: 'Importar Planilha da Semana', body, footer });
  renderIcons();
  document.getElementById('cancelImportarGrade').onclick = App.closeModal;

  function mostrarPreview(rows, file, dataURL) {
    body.innerHTML = progRenderPreviewGrade(rows);
    footer.innerHTML = `<button class="btn" id="cancelImportarGrade2">Cancelar</button><button class="btn btn-primary" id="confirmImportarGrade" ${rows.length ? '' : 'disabled'}>${Icon('check', 15)} Confirmar Importação</button>`;
    renderIcons();
    document.getElementById('cancelImportarGrade2').onclick = App.closeModal;
    document.getElementById('confirmImportarGrade').onclick = () => {
      progImportarGradeSemanal(rows, file.name, dataURL);
      App.closeModal();
    };
  }

  document.getElementById('inputImportarGrade').addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const ehPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);
    App.toast(`Lendo ${ehPdf ? 'PDF' : 'planilha'}...`, 'info');
    const reader = new FileReader();
    reader.onload = async () => {
      const dataURL = reader.result;
      if (ehPdf) {
        try {
          const rows = await progExtrairGradeDoPDF(dataURL);
          mostrarPreview(rows, file, dataURL);
        } catch (err) {
          console.warn('Falha ao ler o PDF:', err);
          App.toast('Não foi possível ler o PDF. Verifique se é o relatório de programação semanal.', 'danger');
        }
      } else {
        Importacao.lerArquivoPlanilha(file, (rows) => mostrarPreview(rows, file, dataURL),
          () => App.toast('Falha ao ler o arquivo. Verifique o formato.', 'danger'));
      }
    };
    reader.onerror = () => App.toast('Falha ao ler o arquivo.', 'danger');
    reader.readAsDataURL(file);
  });
}

function progDataURLtoBlob(dataurl) {
  const arr = dataurl.split(',');
  const mime = (arr[0].match(/:(.*?);/) || [, 'application/octet-stream'])[1];
  const bstr = atob(arr[1]);
  let n = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) u8arr[n] = bstr.charCodeAt(n);
  return new Blob([u8arr], { type: mime });
}
function progNormalizar(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}


/* ------------------------------------- View ------------------------------------- */

// A semana fica salva no localStorage para sobreviver a um F5 — sem isso, recarregar a
// página sempre volta pra semana de hoje, e quem navegou pra outra semana (ex.: pra
// importar uma planilha de uma semana futura) via os dados "sumirem" ao recarregar.
// _v2: a v1 guardava a semana com início no domingo (convenção antiga); trocar a chave
// evita reabrir com um valor salvo sob a convenção velha (semana errada, deslocada).
const PROG_SEMANA_REF_KEY = 'fertgrow_prog_semana_ref_v2';
function progSetSemanaRef(dataISO) {
  _progSemanaRef = progInicioSemana(dataISO);
  try { localStorage.setItem(PROG_SEMANA_REF_KEY, _progSemanaRef); } catch (e) {}
}
let _progSemanaRef = progInicioSemana(localStorage.getItem(PROG_SEMANA_REF_KEY) || new Date().toISOString().slice(0, 10));
let _progDiaDestaque = null; // data (ISO) a destacar/rolar até após "Hoje" ou "Ir para o dia"

Views.programacao = {
  title: 'Programação',
  render() {
    const hojeISO = new Date().toISOString().slice(0, 10);
    const semanaAnteriorInicio = progAddDays(_progSemanaRef, -7);
    const s1 = progAderenciaSemana(semanaAnteriorInicio);
    const dias = progDiasDaSemana(_progSemanaRef);

    // Monta as linhas: uma por OS identificada; arquivos sem OS reconhecida
    // ainda aparecem (com campos em branco) para não perder o anexo de vista.
    const linhas = [];
    let totalOrdens = 0, ordensConcluidas = 0;
    dias.forEach(d => {
      const entry = progEntry(d);
      (entry?.arquivos || []).forEach(a => {
        if (a.ordens && a.ordens.length) {
          a.ordens.forEach(o => {
            linhas.push({ dia: d, arquivo: a, ordem: o });
            totalOrdens++;
            if (progConta(o)) ordensConcluidas++;
          });
        } else {
          linhas.push({ dia: d, arquivo: a, ordem: null });
        }
      });
    });
    const aderencia = totalOrdens ? Math.round((ordensConcluidas / totalOrdens) * 100) : 0;

    return `
      <div class="view-head">
        <div><h1>Programação da Semana</h1><div class="sub">Importe a planilha semanal de OS — o sistema distribui cada OS no dia certo automaticamente</div></div>
        <div class="view-actions">
          <button class="btn" id="btnSyncMelvinProg">${Icon('refresh', 15)} Sincronizar Melvin</button>
          <button class="btn" id="btnImportarGradeProg">${Icon('upload', 15)} Importar Planilha da Semana</button>
          <button class="btn" id="btnPrintProg">${Icon('print', 15)} Imprimir / Salvar PDF</button>
          <button class="btn" id="btnZipProg">${Icon('download', 15)} Baixar anexos (.zip)</button>
          <button class="btn btn-primary" id="btnMailProg">${Icon('mail', 15)} Enviar por e-mail</button>
        </div>
      </div>

      <div class="grid grid-3" style="display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:14px;margin-bottom:18px;">
        <div class="card" style="padding:12px 16px;">
          <div class="flex-between" style="flex-wrap:wrap;gap:10px;">
            <div class="flex" style="gap:10px;align-items:center;">
              <button class="btn btn-sm" id="btnSemanaAnterior">${Icon('arrow-left', 14)}</button>
              <div>
                <div style="font-weight:700;font-size:14px;">Semana de ${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])}</div>
                <div class="cell-tag">${totalOrdens} OS identificada(s) nesta semana</div>
              </div>
              <button class="btn btn-sm" id="btnSemanaProxima">${Icon('arrow-right', 14)}</button>
            </div>
            <div class="flex" style="gap:8px;align-items:center;flex-wrap:wrap;">
              <button class="btn btn-sm" id="btnSemanaHoje">Hoje</button>
              <input type="date" id="progIrParaDia" title="Ir para um dia específico" style="background:var(--surface-2);border:1px solid var(--border);border-radius:8px;padding:7px 9px;color:var(--text);font-size:12.5px;">
            </div>
          </div>
        </div>
        <div class="card" style="padding:12px 16px;">
          <div class="flex-between" style="margin-bottom:8px;">
            <div class="kpi-label">Aderência da Semana</div>
            <span style="font-weight:700;font-size:20px;color:${aderencia===0?'var(--text-muted)':aderencia>=80?'var(--success)':aderencia>=50?'var(--warning)':'var(--danger)'};">${aderencia===0?'—':aderencia+'%'}</span>
          </div>
          <div style="height:8px;border-radius:6px;background:var(--surface-2);overflow:hidden;">
            <div style="height:100%;width:${aderencia}%;background:${aderencia>=80?'var(--success)':aderencia>=50?'var(--warning)':'var(--danger)'};border-radius:6px;transition:width .3s;"></div>
          </div>
          <div class="cell-tag" style="margin-top:8px;">${totalOrdens===0?'Nenhuma OS programada ainda':`${ordensConcluidas} de ${totalOrdens} OS concluídas ou canceladas`}</div>
        </div>
        <div class="card" style="padding:12px 16px;">
          <div class="flex-between" style="margin-bottom:8px;">
            <div class="kpi-label">Aderência S-1 · Semana Anterior (${App.fmtDate(semanaAnteriorInicio)} a ${App.fmtDate(progAddDays(semanaAnteriorInicio, 6))})</div>
            <span style="font-weight:700;font-size:20px;color:${s1.total===0?'var(--text-muted)':s1.aderencia>=80?'var(--success)':s1.aderencia>=50?'var(--warning)':'var(--danger)'};">${s1.total===0?'—':s1.aderencia+'%'}</span>
          </div>
          <div style="height:8px;border-radius:6px;background:var(--surface-2);overflow:hidden;">
            <div style="height:100%;width:${s1.aderencia}%;background:${s1.aderencia>=80?'var(--success)':s1.aderencia>=50?'var(--warning)':'var(--danger)'};border-radius:6px;transition:width .3s;"></div>
          </div>
          <div class="cell-tag" style="margin-top:8px;">${s1.total===0?'Nenhuma OS programada na semana anterior':`${s1.concluidas} de ${s1.total} OS concluídas ou canceladas`}</div>
        </div>
      </div>

      <div class="print-only" style="display:none;margin-bottom:14px;">
        <h2 style="margin:0 0 4px;">FertGrow — Programação da Semana</h2>
        <div>${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])} · Aderência: ${aderencia===0?'—':aderencia+'%'} (${ordensConcluidas}/${totalOrdens})</div>
      </div>

      <div class="table-wrap" style="margin-bottom:22px;">
        <table>
          <thead><tr><th></th><th>Dia</th><th>Nº OS</th><th>Tipo</th><th>Bem</th><th>Serviço</th><th>Área</th><th>Data Início</th><th>Situação</th><th>Arquivo</th><th></th></tr></thead>
          <tbody>
            ${linhas.map(({ dia, arquivo: a, ordem: o }) => `<tr>
                <td>${o ? (o.cancelada
                  ? `<span title="Cancelada${o.motivoCancelamento ? ' — ' + o.motivoCancelamento.replace(/"/g,'&quot;') : ''}" style="color:var(--text-muted);display:inline-flex;">${Icon('x', 15)}</span>`
                  : `<input type="checkbox" class="prog-check-ordem" data-dia="${dia}" data-arquivo="${a.id}" data-ordem="${o.id}" ${o.concluida ? 'checked' : ''}>`) : ''}</td>
                <td class="cell-tag">${progDiaSemanaLabel(dia).replace('-feira', '')} · ${App.fmtDate(dia)}</td>
                <td class="cell-tag">${o?.numero || '—'}</td>
                <td>${o?.tipo ? `<span class="badge badge-${progBadgeTipoOS(o.tipo)}">${o.tipo}</span>` : '—'}</td>
                <td>${o?.bem || '—'}</td>
                <td>${o?.servico || '—'}</td>
                <td>${o?.area || '—'}</td>
                <td class="cell-tag">${o?.dataInicio || '—'}</td>
                <td>${o ? `<span class="badge badge-${o.cancelada ? 'neutral' : o.concluida ? 'success' : 'warning'}" ${o.cancelada && o.motivoCancelamento ? `title="${o.motivoCancelamento.replace(/"/g,'&quot;')}"` : ''}>${o.cancelada ? 'Cancelada' : o.concluida ? 'Realizada' : 'Pendente'}</span>` : '—'}</td>
                <td style="max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;">${a.nome}</td>
                <td><div class="row-actions">
                  ${o ? `<button class="btn btn-sm" data-ver-arquivo="${a.id}" data-dia="${dia}" title="Ver detalhes">${Icon('eye', 14)}</button>` : ''}
                  ${o && !o.cancelada ? `<button class="btn btn-sm" data-cancelar-os data-dia="${dia}" data-arquivo="${a.id}" data-ordem="${o.id}" title="Cancelar OS (com justificativa)">${Icon('x', 14)}</button>` : ''}
                  ${o && o.cancelada ? `<button class="btn btn-sm" data-reabrir-os data-dia="${dia}" data-arquivo="${a.id}" data-ordem="${o.id}" title="Reabrir OS">${Icon('refresh', 14)}</button>` : ''}
                  <a class="btn btn-sm" href="${a.data}" download="${a.nome}" title="Baixar">${Icon('download', 14)}</a>
                  <button class="btn btn-sm btn-danger" data-del-arquivo-prog="${a.id}" data-dia="${dia}" title="Excluir arquivo">${Icon('trash', 14)}</button>
                </div></td>
              </tr>`).join('') || `<tr><td colspan="11"><div class="empty">${Icon('clipboard', 30)}<span>Nenhuma OS nesta semana. Use "Importar Planilha da Semana" no topo da tela.</span></div></td></tr>`}
          </tbody>
        </table>
      </div>

      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px;">
        ${dias.map(d => progRenderDiaCard(d, d === hojeISO)).join('')}
      </div>
    `;
  },
  afterRender() {
    document.getElementById('btnSemanaAnterior').addEventListener('click', () => { progSetSemanaRef(progAddDays(_progSemanaRef, -7)); App.navigate('programacao'); });
    document.getElementById('btnSemanaProxima').addEventListener('click', () => { progSetSemanaRef(progAddDays(_progSemanaRef, 7)); App.navigate('programacao'); });
    document.getElementById('btnSemanaHoje').addEventListener('click', () => {
      const hoje = new Date().toISOString().slice(0, 10);
      progSetSemanaRef(progInicioSemana(hoje));
      _progDiaDestaque = hoje;
      App.navigate('programacao');
    });
    document.getElementById('progIrParaDia').addEventListener('change', (e) => {
      const dia = e.target.value;
      if (!dia) return;
      progSetSemanaRef(progInicioSemana(dia));
      _progDiaDestaque = dia;
      App.navigate('programacao');
    });

    document.getElementById('btnImportarGradeProg').addEventListener('click', () => progAbrirImportarGrade());
    document.getElementById('btnSyncMelvinProg')?.addEventListener('click', async (e) => {
      const btn = e.currentTarget;
      btn.disabled = true;
      const textoOriginal = btn.innerHTML;
      btn.innerHTML = `${Icon('refresh', 15)} Sincronizando…`;
      try {
        const r = MelvinSync.sincronizarProgramacao();
        App.toast(`Programação atualizada a partir das Ordens de Serviço sincronizadas: ${r.diasAtualizados} dia(s), ${r.ordensTotal} OS no total.`, 'success');
        App.navigate('programacao', true);
      } catch (err) {
        App.toast(`Falha ao gerar a programação: ${err.message}`, 'danger');
        btn.disabled = false;
        btn.innerHTML = textoOriginal;
        renderIcons(btn);
      }
    });
    document.getElementById('btnPrintProg').addEventListener('click', () => progAbrirRelatorio());
    document.getElementById('btnZipProg').addEventListener('click', progExportarZip);
    document.getElementById('btnMailProg').addEventListener('click', progEnviarEmail);


    document.querySelectorAll('[data-del-arquivo-prog]').forEach(b => b.addEventListener('click', () => {
      App.confirmAction('Remover este arquivo (e as OS dele) da programação?', () => {
        progRemoverArquivo(b.dataset.dia, b.dataset.delArquivoProg);
        App.toast('Arquivo removido.', 'success');
      });
    }));

    document.querySelectorAll('[data-del-ordem-prog]').forEach(b => b.addEventListener('click', () => {
      App.confirmAction('Remover esta OS da programação do dia?', () => {
        progRemoverOrdem(b.dataset.dia, b.dataset.arquivo, b.dataset.delOrdemProg);
        App.toast('OS removida.', 'success');
      });
    }));

    document.querySelectorAll('[data-ver-arquivo]').forEach(b => b.addEventListener('click', () => {
      const entry = progEntry(b.dataset.dia);
      const arquivo = entry?.arquivos.find(a => a.id === b.dataset.verArquivo);
      if (arquivo) progVerDetalhesArquivo(arquivo, b.dataset.dia);
    }));

    document.querySelectorAll('.prog-check-ordem').forEach(cb => cb.addEventListener('change', () => {
      progToggleOrdem(cb.dataset.dia, cb.dataset.arquivo, cb.dataset.ordem, cb.checked);
    }));

    document.querySelectorAll('[data-cancelar-os]').forEach(b => b.addEventListener('click', () => progAbrirCancelarOS(b.dataset.dia, b.dataset.arquivo, b.dataset.ordem)));
    document.querySelectorAll('[data-reabrir-os]').forEach(b => b.addEventListener('click', () => {
      App.confirmAction('Reabrir esta OS cancelada?', () => {
        progReabrirOrdem(b.dataset.dia, b.dataset.arquivo, b.dataset.ordem);
        App.toast('OS reaberta.', 'success');
        App.navigate('programacao', true);
      });
    }));

    document.querySelectorAll('.prog-obs').forEach(ta => ta.addEventListener('change', () => {
      progSalvarObservacao(ta.dataset.dia, ta.value);
    }));

    const irParaDia = document.getElementById('progIrParaDia');
    if (irParaDia) irParaDia.value = _progDiaDestaque || new Date().toISOString().slice(0, 10);

    if (_progDiaDestaque) {
      const alvo = document.querySelector(`[data-dia-card="${_progDiaDestaque}"]`);
      if (alvo) { alvo.scrollIntoView({ behavior: 'smooth', block: 'center' }); alvo.classList.add('flash-highlight'); }
      _progDiaDestaque = null;
    }
  },
};

function progRenderDiaCard(dataISO, isHoje) {
  const entry = progEntry(dataISO);
  // O card lista as OS do dia diretamente — sem expor o "arquivo" que as trouxe, já que
  // hoje a origem é sempre a mesma planilha/PDF da semana inteira, não um anexo por dia.
  const ordens = (entry?.arquivos || []).flatMap(a => (a.ordens || []).map(o => ({ ...o, _arquivoId: a.id })));
  const observacao = entry?.observacao || '';
  const isD1 = dataISO === progAddDays(new Date().toISOString().slice(0, 10), -1);
  const ad = progAderenciaDia(dataISO);
  return `
    <div class="card" data-dia-card="${dataISO}" style="padding:16px;">
      <div class="flex-between" style="margin-bottom:10px;">
        <div>
          <div style="font-weight:700;font-size:14px;">${progDiaSemanaLabel(dataISO)}</div>
          <div class="cell-tag">${App.fmtDate(dataISO)}</div>
        </div>
        <div class="flex" style="gap:6px;align-items:center;">
          ${isHoje ? '<span class="badge badge-info">Hoje</span>' : ''}
          ${isD1 ? '<span class="badge badge-neutral">D-1</span>' : ''}
          ${ad.total ? `<span class="badge badge-${ad.aderencia >= 80 ? 'success' : ad.aderencia >= 50 ? 'warning' : 'danger'}" title="${ad.concluidas} de ${ad.total} OS concluídas ou canceladas">${ad.aderencia}%</span>` : ''}
        </div>
      </div>
      <div>${ordens.length ? ordens.map(o => `
        <div class="flex-between" style="padding:6px 0;border-bottom:1px solid var(--border-soft);font-size:12.5px;gap:8px;">
          <label class="flex" style="gap:8px;align-items:flex-start;min-width:0;cursor:pointer;">
            <input type="checkbox" class="prog-check-ordem" data-dia="${dataISO}" data-arquivo="${o._arquivoId}" data-ordem="${o.id}" ${o.concluida ? 'checked' : ''} ${o.cancelada ? 'disabled' : ''} style="margin-top:2px;">
            <div style="min-width:0;">
              <div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:180px;${o.cancelada ? 'text-decoration:line-through;color:var(--text-muted);' : ''}">${o.numero ? `OS ${o.numero} · ` : ''}${o.servico || o.bem || '—'}</div>
              <div class="text-muted" style="font-size:10.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:180px;">${o.bem || ''}</div>
            </div>
          </label>
          <button class="btn btn-sm btn-danger" data-del-ordem-prog="${o.id}" data-arquivo="${o._arquivoId}" data-dia="${dataISO}" title="Excluir OS">${Icon('trash', 12)}</button>
        </div>`).join('') : '<div class="text-muted" style="font-size:11.5px;padding:6px 0;">Nenhuma OS neste dia.</div>'}
      </div>
      <textarea class="prog-obs" data-dia="${dataISO}" placeholder="Observações do dia (opcional)" style="width:100%;margin-top:10px;min-height:50px;background:var(--surface-2);border:1px solid var(--border);border-radius:8px;padding:8px;color:var(--text);font-size:12.5px;">${observacao}</textarea>
    </div>`;
}

function progVerDetalhesArquivo(arquivo, dataISO) {
  const body = document.createElement('div');
  body.innerHTML = `
    <p class="text-muted" style="font-size:12.5px;margin-bottom:14px;">${arquivo.ordens.length} Ordem(ns) de Serviço identificada(s) neste arquivo.</p>
    ${arquivo.ordens.map((os, i) => `
      <div class="card" style="padding:14px 16px;margin-bottom:${i === arquivo.ordens.length - 1 ? '0' : '14px'};">
        <div class="flex-between" style="margin-bottom:10px;">
          <div class="flex" style="gap:8px;align-items:center;">
            <div style="font-weight:700;font-size:13.5px;">OS ${os.numero || '—'}</div>
            ${os.tipo ? `<span class="badge badge-${progBadgeTipoOS(os.tipo)}">${os.tipo}</span>` : ''}
          </div>
          <div class="flex" style="gap:12px;align-items:center;">
            ${os.cancelada
              ? `<span class="flex" style="gap:6px;align-items:center;font-size:12.5px;color:var(--text-muted);">${Icon('x', 15)} Cancelada</span>`
              : `<label class="flex" style="gap:6px;align-items:center;font-size:12.5px;cursor:pointer;">
                  <input type="checkbox" class="prog-check-ordem-modal" data-dia="${dataISO}" data-arquivo="${arquivo.id}" data-ordem="${os.id}" ${os.concluida ? 'checked' : ''}>
                  Realizada
                </label>`}
            ${os.cancelada
              ? `<button class="btn btn-sm" data-reabrir-os data-dia="${dataISO}" data-arquivo="${arquivo.id}" data-ordem="${os.id}">${Icon('refresh', 13)} Reabrir</button>`
              : `<button class="btn btn-sm" data-cancelar-os data-dia="${dataISO}" data-arquivo="${arquivo.id}" data-ordem="${os.id}">${Icon('x', 13)} Cancelar OS</button>`}
          </div>
        </div>
        ${os.cancelada ? `<div class="cell-tag" style="margin-bottom:10px;color:var(--text-muted);">${Icon('alert', 12)} Cancelada — ${os.motivoCancelamento || 'sem justificativa registrada'}</div>` : ''}
        <div class="form-grid cols-3" style="margin-bottom:12px;">
          <div><div class="kpi-label">Bem</div><div style="font-weight:600;margin-top:4px;">${os.bem || '—'}</div></div>
          <div><div class="kpi-label">TAG</div><div style="font-weight:600;margin-top:4px;">${os.tag || '—'}</div></div>
          <div><div class="kpi-label">Executante</div><div style="font-weight:600;margin-top:4px;">${os.executante || '—'}</div></div>
          <div><div class="kpi-label">Código Externo</div><div style="font-weight:600;margin-top:4px;">${os.codigoExterno || '—'}</div></div>
          <div><div class="kpi-label">Status (origem)</div><div style="font-weight:600;margin-top:4px;">${os.statusOrigem || '—'}</div></div>
          <div><div class="kpi-label">Área</div><div style="font-weight:600;margin-top:4px;">${os.area || '—'}</div></div>
          <div><div class="kpi-label">Data Início</div><div style="font-weight:600;margin-top:4px;">${os.dataInicio || '—'}</div></div>
          <div class="field-span-2"><div class="kpi-label">Serviço</div><div style="font-weight:600;margin-top:4px;">${os.servico || '—'}</div></div>
          <div><div class="kpi-label">Hora</div><div style="font-weight:600;margin-top:4px;">${os.hora || '—'}</div></div>
          <div class="field-span-2"><div class="kpi-label">Manutenção</div><div style="font-weight:600;margin-top:4px;">${os.manutencao || '—'}</div></div>
          <div><div class="kpi-label">Sequência</div><div style="font-weight:600;margin-top:4px;">${os.sequencia || '—'}</div></div>
          <div><div class="kpi-label">Emissão</div><div style="font-weight:600;margin-top:4px;">${os.emissao || '—'}</div></div>
        </div>
        ${os.etapas.length ? `
          <div style="font-weight:600;font-size:12.5px;margin-bottom:6px;color:var(--text-muted);">Etapas Previstas/Reportadas</div>
          <div class="table-wrap"><table>
            <thead><tr><th>Tarefa</th><th>Etapa</th><th>Descrição</th></tr></thead>
            <tbody>${os.etapas.map(e => `<tr><td class="cell-tag">${e.tarefa}</td><td class="cell-tag">${e.etapa}</td><td>${e.descricao}</td></tr>`).join('')}</tbody>
          </table></div>` : ''}
      </div>`).join('')}
    <div class="mt-8"><a class="btn btn-sm" href="${arquivo.data}" download="${arquivo.nome}">${Icon('download', 13)} Baixar PDF original</a></div>
  `;
  const overlay = App.openModal({ title: arquivo.nome, body, size: 'lg' });
  renderIcons(overlay);
  overlay.querySelectorAll('.prog-check-ordem-modal').forEach(cb => cb.addEventListener('change', () => {
    progToggleOrdem(cb.dataset.dia, cb.dataset.arquivo, cb.dataset.ordem, cb.checked);
  }));
  overlay.querySelectorAll('[data-cancelar-os]').forEach(b => b.addEventListener('click', () => progAbrirCancelarOS(b.dataset.dia, b.dataset.arquivo, b.dataset.ordem)));
  overlay.querySelectorAll('[data-reabrir-os]').forEach(b => b.addEventListener('click', () => {
    App.confirmAction('Reabrir esta OS cancelada?', () => {
      progReabrirOrdem(b.dataset.dia, b.dataset.arquivo, b.dataset.ordem);
      App.toast('OS reaberta.', 'success');
      App.navigate('programacao', true);
    });
  }));
}

/* ------------------------------ Relatório bonito ------------------------------ */
// Gera um documento HTML autônomo (com CSS próprio, sem depender do app) com
// cabeçalho, painel de aderência e a lista de OS por dia — pronto para
// imprimir, salvar como PDF ou anexar/abrir por e-mail.
function progGerarRelatorioHTML() {
  const dias = progDiasDaSemana(_progSemanaRef);
  let totalOrdens = 0, concluidas = 0;
  const diasComOrdens = dias.map(d => {
    const entry = progEntry(d);
    const ordens = [];
    (entry?.arquivos || []).forEach(a => (a.ordens || []).forEach(o => ordens.push(o)));
    totalOrdens += ordens.length;
    concluidas += ordens.filter(o => progConta(o)).length;
    return { data: d, ordens, observacao: entry?.observacao || '' };
  });
  const aderencia = totalOrdens ? Math.round((concluidas / totalOrdens) * 100) : 0;
  const corAderencia = aderencia === 0 ? '#8992A0' : aderencia >= 80 ? '#1E8E5A' : aderencia >= 50 ? '#C9902B' : '#C1443A';
  const aderenciaTexto = aderencia === 0 ? '—' : aderencia + '%';

  const badgeMap = { info: ['#E6F0FA', '#2563A8'], warning: ['#FBF0DC', '#A56C11'], danger: ['#FBE7E6', '#B0362D'], neutral: ['#EEF0F3', '#6B7785'] };
  const badgeTipo = (tipo) => {
    const cor = badgeMap[progBadgeTipoOS(tipo)];
    return `<span class="rel-badge" style="background:${cor[0]};color:${cor[1]};">${tipo}</span>`;
  };

  const blocosDias = diasComOrdens.map(dia => {
    if (!dia.ordens.length) return '';
    return `
      <div class="rel-dia">
        <div class="rel-dia-titulo">${progDiaSemanaLabel(dia.data)} <span>${App.fmtDate(dia.data)}</span></div>
        <table class="rel-tabela">
          <thead><tr><th style="width:22px;"></th><th>Nº OS</th><th>Tipo</th><th>Equipamento/Local</th><th>Serviço</th><th>Situação</th></tr></thead>
          <tbody>
            ${dia.ordens.map(o => `
              <tr>
                <td class="rel-check">${o.cancelada ? '&#8856;' : o.concluida ? '&#10003;' : ''}</td>
                <td>${o.numero || '—'}</td>
                <td>${o.tipo ? badgeTipo(o.tipo) : '—'}</td>
                <td>${o.bem || '—'}</td>
                <td>${o.servico || '—'}</td>
                <td class="${o.cancelada ? 'rel-cancel' : o.concluida ? 'rel-ok' : 'rel-pend'}">${o.cancelada ? 'Cancelada' + (o.motivoCancelamento ? ' — ' + o.motivoCancelamento : '') : o.concluida ? 'Realizada' : 'Pendente'}</td>
              </tr>`).join('')}
          </tbody>
        </table>
        ${dia.observacao ? `<div class="rel-obs">Obs.: ${dia.observacao}</div>` : ''}
      </div>`;
  }).filter(Boolean).join('');

  return `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8">
<title>Programação de Manutenção — Semana de ${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])}</title>
<style>
  @page { size: A4; margin: 16mm 14mm; }
  * { box-sizing: border-box; }
  body { font-family: 'Segoe UI', Arial, sans-serif; color: #1c2430; margin:0; padding:24px; background:#fff; }
  .rel-header { display:flex; align-items:center; justify-content:space-between; border-bottom:3px solid #1E8E5A; padding-bottom:14px; margin-bottom:22px; }
  .rel-brand { display:flex; align-items:center; gap:10px; }
  .rel-brand-mark { width:38px;height:38px;border-radius:10px;background:#fff;border:1px solid #e2e6ea;display:flex;align-items:center;justify-content:center;flex-shrink:0;padding:4px; }
  .rel-brand-mark img { width:100%;height:100%;object-fit:contain;display:block; }
  .rel-brand-text strong { font-size:16px; display:block; }
  .rel-brand-text small { color:#6b7785; font-size:11px; }
  .rel-titulo { text-align:right; }
  .rel-titulo h1 { font-size:16px; margin:0 0 2px; }
  .rel-titulo div { font-size:11.5px; color:#6b7785; }
  .rel-painel { display:flex; gap:16px; margin-bottom:26px; }
  .rel-card { flex:1; border:1px solid #e2e6ea; border-radius:10px; padding:14px 16px; }
  .rel-card .lbl { font-size:10.5px; text-transform:uppercase; letter-spacing:.03em; color:#8992a0; margin-bottom:6px; }
  .rel-aderencia-num { font-size:32px; font-weight:700; color:${corAderencia}; }
  .rel-barra { height:10px; border-radius:6px; background:#eef0f3; overflow:hidden; margin-top:8px; }
  .rel-barra > div { height:100%; background:${corAderencia}; }
  .rel-resumo-linha { display:flex; justify-content:space-between; font-size:12px; padding:4px 0; border-bottom:1px dashed #e2e6ea; }
  .rel-resumo-linha:last-child { border-bottom:none; }
  .rel-dia { margin-bottom:20px; break-inside: avoid; }
  .rel-dia-titulo { font-size:13px; font-weight:700; background:#f3f6f4; border-left:4px solid #1E8E5A; padding:7px 10px; margin-bottom:8px; }
  .rel-dia-titulo span { font-weight:400; color:#6b7785; margin-left:8px; font-size:11.5px; }
  table.rel-tabela { width:100%; border-collapse:collapse; font-size:11.5px; }
  table.rel-tabela th { text-align:left; background:#fafbfc; border-bottom:2px solid #e2e6ea; padding:6px 8px; font-size:10.5px; text-transform:uppercase; letter-spacing:.02em; color:#6b7785; }
  table.rel-tabela td { padding:6px 8px; border-bottom:1px solid #eef0f3; vertical-align:top; }
  .rel-check { text-align:center; font-weight:700; color:#1E8E5A; }
  .rel-ok { color:#1E8E5A; font-weight:600; }
  .rel-pend { color:#C9902B; font-weight:600; }
  .rel-cancel { color:#6b7785; font-weight:600; }
  .rel-badge { display:inline-block; padding:2px 9px; border-radius:20px; font-size:10px; font-weight:600; white-space:nowrap; }
  .rel-obs { font-size:11px; color:#6b7785; padding:6px 10px; font-style:italic; }
  .rel-footer { margin-top:26px; padding-top:10px; border-top:1px solid #e2e6ea; font-size:10px; color:#a2a9b3; text-align:center; }
  .rel-vazio { text-align:center; color:#8992a0; padding:34px; font-size:12.5px; border:1px dashed #e2e6ea; border-radius:10px; }
  @media print { body { padding:0; } }
</style></head>
<body>
  <div class="rel-header">
    <div class="rel-brand">
      <div class="rel-brand-mark"><img src="data:image/png;base64,${LOGO_FERTGROW_B64}" alt="FertGrow"></div>
      <div class="rel-brand-text"><strong>FertGrow</strong><small>CMMS · Planejamento e Controle de Manutenção</small></div>
    </div>
    <div class="rel-titulo">
      <h1>Programação de Manutenção</h1>
      <div>Semana de ${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])}</div>
    </div>
  </div>

  <div class="rel-painel">
    <div class="rel-card">
      <div class="lbl">Aderência da Semana</div>
      <div class="rel-aderencia-num">${aderenciaTexto}</div>
      <div class="rel-barra"><div style="width:${totalOrdens === 0 ? 0 : aderencia}%;"></div></div>
      <div style="font-size:11px;color:#6b7785;margin-top:6px;">${totalOrdens === 0 ? 'Nenhuma OS programada nesta semana' : `${concluidas} de ${totalOrdens} OS concluídas ou canceladas`}</div>
    </div>
    <div class="rel-card">
      <div class="lbl">Resumo por Dia</div>
      ${diasComOrdens.map(d => `<div class="rel-resumo-linha"><span>${progDiaSemanaLabel(d.data)}</span><span>${d.ordens.filter(o => progConta(o)).length}/${d.ordens.length} OS</span></div>`).join('')}
    </div>
  </div>

  ${blocosDias || '<div class="rel-vazio">Nenhuma OS programada para esta semana.</div>'}

  <div class="rel-footer">Gerado pelo FertGrow CMMS em ${new Date().toLocaleString('pt-BR')}</div>
</body></html>`;
}

function progAbrirRelatorio() {
  const html = progGerarRelatorioHTML();
  const blob = new Blob([html], { type: 'text/html' });
  const url = URL.createObjectURL(blob);
  const win = window.open(url, '_blank');
  if (!win) { App.toast('Permita pop-ups para abrir o relatório.', 'danger'); return; }
  win.addEventListener('load', () => { win.focus(); win.print(); });
  win.addEventListener('afterprint', () => URL.revokeObjectURL(url));
}

function progBaixarRelatorioHTML() {
  const html = progGerarRelatorioHTML();
  const blob = new Blob([html], { type: 'text/html' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `programacao-semana-${_progSemanaRef}.html`;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}

async function progExportarZip() {
  if (typeof JSZip === 'undefined') { App.toast('Biblioteca de compactação indisponível.', 'danger'); return; }
  const dias = progDiasDaSemana(_progSemanaRef);
  const zip = new JSZip();
  let total = 0;
  dias.forEach(d => {
    const entry = progEntry(d);
    if (entry && entry.arquivos.length) {
      const pasta = zip.folder(`${progDiaSemanaLabel(d)} - ${App.fmtDate(d).replace(/\//g, '-')}`);
      entry.arquivos.forEach(a => { pasta.file(a.nome, progDataURLtoBlob(a.data)); total++; });
    }
  });
  if (!total) { App.toast('Nenhum arquivo anexado nesta semana.', 'danger'); return; }
  App.toast('Gerando arquivo ZIP da semana...', 'info');
  const blob = await zip.generateAsync({ type: 'blob' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `programacao-semana-${_progSemanaRef}.zip`;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
  App.toast('ZIP da semana pronto para download.', 'success');
}

function progEnviarEmail() {
  const dias = progDiasDaSemana(_progSemanaRef);
  let totalOrdens = 0, concluidas = 0;
  const linhas = dias.map(d => {
    const entry = progEntry(d);
    if (!entry || !entry.arquivos.length) return `${progDiaSemanaLabel(d)} (${App.fmtDate(d)}): sem OS programadas`;
    const detalhe = entry.arquivos.map(a => {
      if (a.ordens && a.ordens.length) {
        return a.ordens.map(o => {
          totalOrdens++; if (progConta(o)) concluidas++;
          const situacao = o.cancelada ? `Cancelada${o.motivoCancelamento ? ' - ' + o.motivoCancelamento : ''}` : o.concluida ? 'Realizada' : 'Pendente';
          return `OS ${o.numero || '—'} · ${o.bem || ''} · ${o.servico || ''} [${situacao}]`;
        }).join('; ');
      }
      return a.nome;
    }).join('; ');
    const obs = entry.observacao ? ` — Obs: ${entry.observacao}` : '';
    return `${progDiaSemanaLabel(d)} (${App.fmtDate(d)}): ${detalhe}${obs}`;
  }).join('\n');
  const aderencia = totalOrdens ? Math.round((concluidas / totalOrdens) * 100) : 0;
  const aderenciaTxt = aderencia === 0 ? '—' : aderencia + '%';
  const assunto = `Programação de Manutenção — Semana de ${App.fmtDate(dias[0])} a ${App.fmtDate(dias[6])} (Aderência ${aderenciaTxt})`;
  const corpo = `Segue a programação de manutenção da semana (aderência: ${aderenciaTxt} — ${concluidas}/${totalOrdens} OS concluídas ou canceladas):\n\n${linhas}\n\nUm relatório em HTML, pronto para visualizar ou imprimir, foi baixado automaticamente — anexe-o a este e-mail antes de enviar (ou use o botão "Imprimir / Salvar PDF" para gerar um PDF).`;
  progBaixarRelatorioHTML();
  window.location.href = `mailto:?subject=${encodeURIComponent(assunto)}&body=${encodeURIComponent(corpo)}`;
  App.toast('Relatório bonito baixado — anexe-o ao e-mail que acabamos de abrir.', 'info');
}
